foreach ( $locations as $slug => $loc ) {
  $post_id = $loc['id'];

  // Try to find by ID first, fallback to slug search
  $post = get_post( $post_id );
  if ( ! $post ) {
    $results = get_posts(['name'=>$slug,'post_type'=>'page','post_status'=>'any','numberposts'=>1]);
    if ( $results ) $post_id = $results[0]->ID;
  }

  if ( $post_id ) {
    wp_update_post([
      'ID'           => $post_id,
      'post_title'   => $loc['title'],
      'post_content' => $loc['content'],
      'post_status'  => 'publish',
    ]);
    // SEO meta
    update_post_meta( $post_id, '_yoast_wpseo_title',    $loc['title'] . ' | SearchEngineOptimization.ae' );
    update_post_meta( $post_id, '_yoast_wpseo_metadesc', 'Professional SEO services in ' . explode(' —', $loc['title'])[0] . '. First-page Google rankings, Arabic SEO, local search optimisation. Free audit available.' );
    echo "✅ {$loc['title']} (ID $post_id)\n";
  } else {
    echo "⚠️  Page not found for slug: $slug\n";
  }
}

